package main

import (
	"encoding/json"
	"fmt"

	"github.com/bytedance/sonic"
	"github.com/cosmos/cosmos-sdk/types"
)

func main() {
	// Test that cosmos-sdk types serialize correctly with sonic
	config := types.GetConfig()
	config.SetBech32PrefixForAccount("defra", "defrapub")

	// Test struct that might be used in cosmos-sdk
	type TestData struct {
		Name  string `json:"name"`
		Value int64  `json:"value"`
	}

	data := TestData{
		Name:  "test",
		Value: 12345,
	}

	// Test with sonic
	sonicBytes, err := sonic.Marshal(data)
	if err != nil {
		panic(fmt.Sprintf("sonic marshal failed: %v", err))
	}

	// Test with standard json for comparison
	stdBytes, err := json.Marshal(data)
	if err != nil {
		panic(fmt.Sprintf("std json marshal failed: %v", err))
	}

	fmt.Printf("Sonic output: %s\n", string(sonicBytes))
	fmt.Printf("Std JSON output: %s\n", string(stdBytes))

	// Test unmarshaling
	var sonicData, stdData TestData
	if err := sonic.Unmarshal(sonicBytes, &sonicData); err != nil {
		panic(fmt.Sprintf("sonic unmarshal failed: %v", err))
	}
	if err := json.Unmarshal(stdBytes, &stdData); err != nil {
		panic(fmt.Sprintf("std json unmarshal failed: %v", err))
	}

	fmt.Printf("Sonic unmarshal result: %+v\n", sonicData)
	fmt.Printf("Std JSON unmarshal result: %+v\n", stdData)

	fmt.Println("✅ All JSON serialization tests passed with sonic v1.14.2 and cosmos-sdk")
}

